 function stopPolling(){if(state.qrTimer)clearTimeout(state.qrTimer);state.qrTimer=null;state.qrId=null}
 function qrExpireTime(value){if(!value)return 0;if(typeof value==='number')return value<100000000000?value*1000:value;var numeric=Number(value);if(Number.isFinite(numeric)&&numeric>0)return numeric<100000000000?numeric*1000:numeric;var t=Date.parse(value);return Number.isFinite(t)?t:0}
 async function pollLogin(id){if(state.qrId!==id)return;if(state.qrExpiry&&Date.now()>state.qrExpiry){stopPolling();$('qr-status').textContent='二维码已过期。请手动重新生成。';return}try{var result=await api('/api/login/poll',{method:'POST',data:{id:id}});if(state.qrId!==id)return;var s=String(result.status||'').toLowerCase();$('qr-status').textContent=result.message||({waiting:'等待扫码',scanned:'已扫码，请在手机端确认',pending:'等待手机确认',expired:'二维码已过期',success:'登录成功',confirmed:'登录已确认'}[s]||'等待扫码或手机确认');if(result.account&&result.account.logged_in||['success','confirmed','logged_in','complete','completed'].indexOf(s)>=0){stopPolling();if(result.account)accountDisplay(result.account);await bootstrap();$('qr-status').textContent='账号已连接。';$('qr-area').hidden=true;status('account-status','账号状态已更新。','success');return}if(['expired','cancelled','canceled','failed','error'].indexOf(s)>=0){stopPolling();return}state.qrTimer=setTimeout(function(){pollLogin(id)},3000)}catch(e){if(state.qrId===id){stopPolling();$('qr-status').textContent=message(e);status('account-status','登录状态读取中断。请核实账号状态，必要时手动重新扫码。','error')}}}
 $('login-start').addEventListener('click',async function(){var button=this;await busy(button,async function(){stopPolling();status('account-status','正在生成登录二维码…');try{var result=await api('/api/login/start',{method:'POST',data:{}});if(!result.id||typeof result.svg!=='string')throw new Error('服务没有返回有效的登录二维码。');if(state.qrUrl)URL.revokeObjectURL(state.qrUrl);state.qrUrl=URL.createObjectURL(new Blob([result.svg],{type:'image/svg+xml'}));$('qr-image').src=state.qrUrl;$('qr-area').hidden=false;$('qr-status').textContent='等待扫码，请在手机应用中确认登录。';state.qrId=result.id;state.qrExpiry=qrExpireTime(result.expires_at);status('account-status','二维码已生成，页面每 3 秒读取一次登录状态。');state.qrTimer=setTimeout(function(){pollLogin(result.id)},3000)}catch(e){status('account-status',message(e),'error')}})});
