 $('logout').addEventListener('click',async function(){if(!window.confirm('确认退出此云端服务保存的 Bilibili 账号吗？'))return;await busy(this,async function(){try{stopPolling();await api('/api/logout',{method:'POST',data:{}});$('qr-area').hidden=true;await bootstrap();status('account-status','已退出云端账号。','success')}catch(e){status('account-status',message(e),'error')}})});
 [['view-account','bilibili_account',{}],['view-my-videos','bilibili_my_videos',{page:1}],['view-space','bilibili_space',{}]].forEach(function(entry){$(entry[0]).addEventListener('click',async function(){await busy(this,async function(){status('account-status','正在读取…');try{var result=await tool(entry[1],entry[2]);renderResult($('account-results'),result);assertTool(result);status('account-status','读取已完成。','success')}catch(e){status('account-status',message(e),'error')}})})});
 function composeKind(){var kind=$('action-kind').value;$('action-video-fields').hidden=['dynamic.publish','profile.update','space.notice'].indexOf(kind)>=0;$('action-url').required=!$('action-video-fields').hidden;$('reply-fields').hidden=kind!=='reply.create';$('reply-root').required=kind==='reply.create';$('reply-parent').required=kind==='reply.create';$('danmaku-fields').hidden=kind!=='danmaku.send';$('action-message-label').textContent=kind==='profile.update'?'新空间签名':kind==='space.notice'?'新空间公告':kind==='dynamic.publish'?'动态正文':kind==='reply.create'?'回复内容':kind==='danmaku.send'?'弹幕文字':'评论内容';$('action-message').maxLength=kind==='profile.update'?70:kind==='space.notice'?150:20000;$('action-message-hint').textContent=kind==='profile.update'?'空间签名最多 70 字。':kind==='space.notice'?'空间公告最多 150 字，确认后会覆盖原公告。':kind==='dynamic.publish'?'此处准备文字动态，确认后将提交平台发布。':'请在确认草稿时再次核对目标视频和内容。'}
 $('action-kind').addEventListener('change',composeKind);composeKind();
 function extractDraftId(result){var candidates=[];if(result&&result.draft)candidates.push(result.draft);if(result)candidates.push(result);if(result&&Array.isArray(result.content))result.content.forEach(function(item){if(item.type==='text'){try{var parsed=JSON.parse(item.text);if(parsed.draft)candidates.push(parsed.draft);candidates.push(parsed)}catch(e){}}});for(var i=0;i<candidates.length;i++){var o=candidates[i];if(o&&typeof o==='object'){if(o.draftId)return String(o.draftId);if(o.draft_id)return String(o.draft_id);if(o.id&&(o.kind||o.payload||o.status))return String(o.id)}}return null}
 async function prepareAction(kind,payload){var result=await tool('bilibili_prepare_action',{kind:kind,payload:payload});assertTool(result);var id=extractDraftId(result);await loadDrafts();if(id)await openDraft(id);else{switchTab('account');status('drafts-status','草稿准备请求已返回，请检查下方列表。');if(!state.drafts.length)renderResult($('account-results'),result)}return result}
 $('action-form').addEventListener('submit',async function(event){event.preventDefault();var button=this.querySelector('button[type="submit"]');var kind=$('action-kind').value;var text=$('action-message').value.trim();if(!text){$('action-message').focus();return}var payload;if(kind==='dynamic.publish')payload={text:text};else if(kind==='profile.update')payload={sign:text};else if(kind==='space.notice')payload={notice:text};else{payload={url:$('action-url').value.trim(),message:text};if(!payload.url){$('action-url').focus();return}if(kind==='reply.create'){payload.root=$('reply-root').value.trim();payload.parent=$('reply-parent').value.trim();if(!/^\d+$/.test(payload.root)||!/^\d+$/.test(payload.parent)){status('action-status','评论 root 和 parent 请填写完整数字 ID。','error');return}}if(kind==='danmaku.send'){var seconds=Number($('danmaku-time').value);if(!Number.isFinite(seconds)||seconds<0){status('action-status','请填写有效的视频时间。','error');return}payload.progress_seconds=seconds;payload.color=parseInt($('danmaku-color').value.slice(1),16);payload.mode=Number($('danmaku-mode').value)}}await busy(button,async function(){status('action-status','正在保存草稿…');try{await prepareAction(kind,payload);status('action-status','草稿已保存。请检查完整内容后决定是否执行。','success')}catch(e){status('action-status',message(e),'error');notify(message(e),true)}})});
 function draftStatus(draft){return String(draft.status||'pending').toLowerCase()}
 function canApprove(draft){return ['pending','prepared','draft','awaiting_approval'].indexOf(draftStatus(draft))>=0}
 function exactTarget(draft){var p=draft.payload||{};var kind=draft.kind||'';var parts=[];var account=(state.boot||{}).account||{};if(draft.target)parts.push(typeof draft.target==='string'?draft.target:JSON.stringify(draft.target));if(p.url)parts.push('视频：'+p.url);if(p.bvid)parts.push('BV 号：'+p.bvid);if(p.aid)parts.push('av 号：'+p.aid);if(p.cid)parts.push('视频分 P ID：'+p.cid);if(p.root)parts.push('评论 root：'+p.root);if(p.parent)parts.push('回复目标 parent：'+p.parent);if(p.progress_seconds!==undefined)parts.push('视频时间：'+p.progress_seconds+' 秒');if(p.mid)parts.push('目标 UID：'+p.mid);if(['dynamic.publish','profile.update','space.notice','video.submit','video.edit'].indexOf(kind)>=0)parts.push('账号：'+(draft.account_name||account.name||'以执行时绑定账号为准')+' / UID '+(draft.account_mid||account.mid||'未提供'));if(p.uploadId)parts.push('云端视频 ID：'+p.uploadId);if(kind==='video.submit'||kind==='video.edit'){parts.push('标题：'+(p.title||'未提供'));parts.push('分区 ID：'+(p.tid||'未提供'))}return parts.length?parts.join('\n'):'目标详情请核对下方完整内容。'}
 function actionWarning(kind){if(kind==='video.submit')return '确认后会向 Bilibili 提交作品投稿及完整投稿信息，作品可能对外公开。投稿提交后，本页面无法撤回本次提交；审核和可见状态由平台决定。';if(kind==='video.edit')return '确认后会修改指定已投稿作品，并可能追加上传的视频分 P。作品信息可能公开可见，本页面不提供自动恢复或撤回。请核对作品 av 号与完整内容。';if(kind==='profile.update')return '确认后会立即修改绑定账号的公开空间签名。本次操作会覆盖原签名，且本页面不提供自动恢复。';if(kind==='space.notice')return '确认后会立即修改绑定账号的公开空间公告。本次操作会覆盖原公告，且本页面不提供自动恢复。';if(kind==='dynamic.publish')return '确认后会以绑定账号向 Bilibili 发布此文字动态，内容可能公开可见。发布后，本页面不提供撤回或删除功能。';if(kind==='danmaku.send')return '确认后会以绑定账号向指定视频的指定时间发送弹幕，其他观众可能看到。本页面不提供撤回或删除功能。';if(kind==='reply.create')return '确认后会以绑定账号向指定评论发布回复，内容可能公开可见。请核对视频、root 和 parent；本页面不提供撤回或删除功能。';return '确认后会以绑定账号向指定视频发布评论，内容可能公开可见。本页面不提供撤回或删除功能。'}
 async function loadDrafts(){var response=await api('/api/drafts');state.drafts=Array.isArray(response.drafts)?response.drafts:[];var list=$('drafts-list');list.replaceChildren();$('draft-total').textContent=state.drafts.length?'('+state.drafts.length+')':'';if(!state.drafts.length){var empty=node('div','empty');empty.appendChild(node('strong','','还没有保存的草稿'));empty.appendChild(node('p','','在上方准备互动内容，或上传视频后保存投稿草稿。'));list.appendChild(empty);return}state.drafts.forEach(function(draft){var row=node('article','draft-row');var info=node('div','draft-info');info.appendChild(node('h3','',kindNames[draft.kind]||draft.kind||'内容草稿'));var target=node('p','draft-target',exactTarget(draft));target.title=exactTarget(draft);info.appendChild(target);info.appendChild(node('p','',formatDate(draft.created_at)));row.appendChild(info);var controls=node('div','draft-actions');var s=draftStatus(draft);controls.appendChild(node('span','badge'+(canApprove(draft)?' warn':['succeeded','success','completed'].indexOf(s)>=0?' good':''),statusNames[s]||s));var button=node('button','btn small',canApprove(draft)?'查看并确认':'查看详情');button.type='button';button.addEventListener('click',async function(){await busy(button,async function(){try{await openDraft(draft.id)}catch(e){notify(message(e),true)}})});controls.appendChild(button);row.appendChild(controls);list.appendChild(row)})}
 async function openDraft(id){if(!id)throw new Error('草稿没有有效 ID。');var response=await api('/api/drafts/'+encodeURIComponent(id));var draft=response.draft||response;state.activeDraft=draft;var allowed=canApprove(draft);$('draft-dialog-title').textContent=(allowed?'确认':'查看')+(kindNames[draft.kind]||'内容草稿');$('draft-target').textContent=exactTarget(draft);$('draft-target').style.whiteSpace='pre-wrap';$('draft-warning').textContent=allowed?actionWarning(draft.kind):'当前状态：'+(statusNames[draftStatus(draft)]||draftStatus(draft))+'。此草稿不会在这里再次执行。';$('draft-payload').textContent=JSON.stringify(draft.payload||{},null,2);$('draft-check').checked=false;$('draft-check-wrap').hidden=!allowed;$('draft-approve').hidden=!allowed;$('draft-approve').disabled=true;$('draft-approve').textContent=draft.kind==='profile.update'?'确认修改签名':draft.kind==='space.notice'?'确认修改公告':draft.kind==='video.submit'?'确认提交投稿':draft.kind==='video.edit'?'确认修改作品':'确认发布';status('draft-confirm-status','');var hasResult=draft.result!==undefined&&draft.result!==null||draft.error;$('draft-result-wrap').hidden=!hasResult;if(hasResult)renderResult($('draft-result'),draft.result||{content:[{type:'text',text:typeof draft.error==='string'?draft.error:JSON.stringify(draft.error,null,2)}]});if(!$('draft-dialog').open)$('draft-dialog').showModal()}
